import type { Tafel } from "./plural";

/**
 * Die dänische Tafel (WI-0210) - die achte Sprache. Aufbau und Kommentare sind die der deutschen
 * Quelle: Wer einen Schlüssel sucht, findet ihn an derselben Stelle, und ein `diff` gegen `de.ts`
 * zeigt nur Text.
 *
 * 🔴 **Für DSA gibt es keine dänische Ausgabe.** Die Begriffe sind hier gesetzt, in schlichtem
 * Dänisch, und gelten von nun an; die Liste steht im Work Item WI-0210 §2.2. Spätere Sitzungen
 * übernehmen sie, statt neu zu wählen.
 *
 * 🔴 **Namen werden nicht übersetzt:** Orte, Wege, Kartenserien, die Monate (Praios … Rahja), die
 * Währungen (`Dukat`, `Silbertaler`, `Heller`), die Werktitel und `Schritt` in der Maßstabsleiste.
 * „Aventurien“ heißt auf Dänisch **Aventurien**, wie im Deutschen.
 *
 * 🪤 **Aufschriften stehen im Infinitiv ohne `at`** („Gem“, „Afbryd“, „Luk“ sind Imperative, die im
 * Dänischen zugleich die übliche Form einer Aufschrift sind und keine Anrede tragen).
 */
