    "transportInfo.button": "Forklar transportmidler",
    "transportInfo.button.title": "Hvor hurtigt hvert transportmiddel er: på hver vejtype, i bjerget og i luften",
    "transportInfo.intro":
        "Hvor hurtigt en rejse kommer frem, afhænger af transportmidlet *og* af vejtypen. En gruppe til fods når på rigsvejen {road} mil i timen, på et bjergpas kun {pass}. Tavlerne nævner mil om dagen og tempoet i mil i timen (1 mil = 1.000 Schritt, cirka 1 km).",
    "transportInfo.landTravel": "Landrejse",
    "transportInfo.riverTravel": "Flodrejse",
    "transportInfo.seaTravel": "Havrejse",
