    "transportInfo.water.miles": "Mil om dagen",
    "transportInfo.water.hours": "Timer om dagen",
    "transportInfo.water.speed": "Mil/t",
    "transportInfo.water.downstream": "medstrøms",
    "transportInfo.water.upstream": "modstrøms",
