        "{name}: {hours} timers sejlads om dagen, derefter {rest} timers hvil for anker eller i havn.",
    // Erklärende Hinweise je Schiff (Geographia Aventurica, Schifffahrt und Flussfahrt); ohne Zahlen, Preise und Orte.
    // Ein Hinweis, den mehrere Schiffe teilen (`oaredCargo`), hat einen Schlüssel und steht je Reise einmal.
    "planner.ships.note.bargeHelp":
        "{name}: Billig passage forudsætter medarbejde; uden medarbejde er den tydeligt dyrere.",
    "planner.ships.note.bargeSleep": "Passagerer sover på enkle trækpramme oftest ved fragten eller på dækket.",
    "planner.ships.note.sailerWaters": "Flodsejlere kræver tilstrækkelig brede og godt sejlbare farvande.",
    "planner.ships.note.riverGalley": "{name}: Hurtigt passager- og kurerskib.",
    "planner.ships.note.oaredCargo": "Roskibe har kun begrænset lastrum.",
    "planner.ships.note.rowboat":
        "{name}: Overfarter forhandles oftest med lokale bådførere; på farlige eller dårligt tilgængelige farvande kan de være dyre.",
    "planner.ships.note.cargoPort": "Havneophold tjener omladning samt påfyldning af vand og proviant.",
    "planner.ships.note.fastComfort": "Hurtige skibe byder oftest på mere komfortabel, men tydeligt dyrere passage.",
    "planner.ships.note.dromone": "{name}: Bygget til hurtig kurerdrift og kun i begrænset omfang egnet som fragtskib.",
    "planner.ships.noRest": "Med {hours} rejsetimer om dagen regner ruten uden hvil, også om bord.",
    // Landschaften und politische Gebiete stehen in EINER Klappbox (WI-0081, Betreiber 2026-10-05): Jede Sprache trägt den
