    "inhalte.pfad.info": "Wiki-oprindelse og redaktion",
    "inhalte.info.text":
        "Dette vindue vedligeholder indhold, der ikke er kortobjekter. En kilde er en fælles katalogindtastning; dens anvendelser tilhører de enkelte objekter. Et litteraturværk bærer sine ordnede start- og spillesteder. En forekomst (fauna, flora, varer, arter) bærer sine steder med forhåndsvisning af resultater og sine regler skrivebeskyttet. Det, der stammer fra Legacy eller wikien, forbliver markeret som sådan; en ændret værdi er beskyttet før næste synkronisering. Et korpus er tilbuddet bag kilderne på et domæne; ved et belæg gælder dets oplysninger for alle kilder på domænet.",
