    "inhalte.vorkommen.text.woerter.richtungen": "Retninger",
    "inhalte.vorkommen.text.woerter.beziehungen": "Tilknytninger",
    "inhalte.vorkommen.text.woerter.kategorien": "Kategorier",
    "inhalte.vorkommen.text.ref.aufbau": "Tekstens opbygning",
    "inhalte.vorkommen.text.ref.quelle.name": "Kilde",
    "inhalte.vorkommen.text.ref.quelle.text":
        "gælder for alle efterfølgende indtastninger til næste Quelle-linje; »Quelle: –« afslutter den. Siderne står efter », S.«.",
    "inhalte.vorkommen.text.ref.kopf.name": "Overskrift",
    "inhalte.vorkommen.text.ref.kopf.text":
        "Navn i begyndelsen af linjen; kategori i parentes. Indtastninger med samme navn: »(Flora, [[Wiki-Titel]])«. Findes indtastningen ikke: »(Flora, neu)«.",
    "inhalte.vorkommen.text.ref.regel.name": "Regel",
    "inhalte.vorkommen.text.ref.regel.text":
        "En linje »| Beziehung = Ausdruck« som en parameter i wikiens infoboks (Verbreitung, Herkunft, Regionen, Vorkommen); den må stå flere gange. En indrykket linje uden »|« fortsætter udtrykket i linjen over.",
    "inhalte.vorkommen.text.ref.zeichen.name": "Tegn",
    "inhalte.vorkommen.text.ref.zeichen.neueRegel": "ny regel",
    "inhalte.vorkommen.text.ref.zeichen.oder": "eller",
    "inhalte.vorkommen.text.ref.zeichen.und": "og",
    "inhalte.vorkommen.text.ref.zeichen.ohne": "uden",
    "inhalte.vorkommen.text.ref.zeichen.gilt": "Tegn tæller kun uden for »[[…]]« og »(…)«.",
    "inhalte.vorkommen.text.ref.glied.name": "Led",
    "inhalte.vorkommen.text.ref.glied.text":
        "Mellem tegnene står et led, og et led er én betingelse i regeleditoren. Dets dele står i vilkårlig rækkefølge, hver højst én gang:",
    "inhalte.vorkommen.text.ref.arten.name": "Landskabstyper",
    "inhalte.vorkommen.text.ref.arten.oder": "(indbyrdes ELLER)",
    "inhalte.vorkommen.text.ref.flaeche.name": "Område",
    "inhalte.vorkommen.text.ref.flaeche.ohneIn":
        "uden »in«, når navnet ikke er en landskabstype (områderne »Meer« og »See« kræver »in«)",
    "inhalte.vorkommen.text.ref.flaeche.mehrdeutig": "ved flertydigt navn",
    "inhalte.vorkommen.text.ref.flaeche.wartet": "(området findes endnu ikke)",
    "inhalte.vorkommen.text.ref.klima.name": "Klima",
    "inhalte.vorkommen.text.ref.lage.name": "Placering",
    "inhalte.vorkommen.text.ref.lage.zwischen": "(mellem stederne »–«, »-« eller »bis«)",
    "inhalte.vorkommen.text.ref.namen":
        "Navne står altid i »[[…]]« (landskabstyper, områder, steder, kilder); derfor må de indeholde komma, kolon, bindestreg og »und«. »[[Ziel|Anzeige]]« og påhængte bogstaver (»[[Steppe]]n«) er tilladt; målet tæller. Et område findes først via sin wikititel, så via sit navn; er det flertydigt, spørger forhåndsvisningen og skriver »[[#Kennung|Name]]«. Tilføjelser i parentes findes kun som »(wartet)«. Store og små bogstaver, ß/ss og accenter tæller ikke i sammenligningen, så længe resultatet forbliver entydigt. Der er en øvre grænse pr. regel og pr. indtastning; fundet nævner den. Et klik på et ord indsætter det ved markøren.",
    "inhalte.vorkommen.text.ref.unterschied.kopf": "Én forskel fra wikien:",
    "inhalte.vorkommen.text.ref.unterschied.text":
        "Strengt fra venstre mod højre, uden fortrin: »[[A]], [[B]]: [[C]]« betyder »(A eller B) og C«, og »[[A]] außer [[X]], [[B]]« betyder »(A uden X) eller B«. Wikien læser »A, B: C« anderledes, nemlig som »A, eller C i B«: Der er kun det sidste led før kolonet rammen. Hvor rammen står først (»[[Aventurien]]: [[Meridiana]], [[Orkland]]«), læser begge ens.",
    "inhalte.vorkommen.text.n.eintraege.one": "{n} indtastning",
    "inhalte.vorkommen.text.n.eintraege.other": "{n} indtastninger",
    "inhalte.vorkommen.text.n.eintraegeAn.one": "{n} indtastning",
    "inhalte.vorkommen.text.n.eintraegeAn.other": "{n} indtastninger",
    "inhalte.vorkommen.text.n.regeln.one": "{n} regel",
    "inhalte.vorkommen.text.n.regeln.other": "{n} regler",
    "inhalte.vorkommen.text.n.rueckfragen.one": "{n} spørgsmål",
    "inhalte.vorkommen.text.n.rueckfragen.other": "{n} spørgsmål",
    "inhalte.vorkommen.text.n.fehler.one": "{n} fejl",
    "inhalte.vorkommen.text.n.fehler.other": "{n} fejl",
    // Vorkommen ohne Wiki-Artikel (WI-0254, Runde 3b, Vali wählte B).
    "inhalte.vorkommen.neu.name": "Indtastningens navn",
    "inhalte.vorkommen.neu.platzhalter": "Forekomstens navn",
    "inhalte.vorkommen.neu.unvollstaendig": "Navnet mangler endnu.",
    "inhalte.vorkommen.neu.hinweis":
        "En indtastning uden wiki-artikel får sin egen Avesmaps-id og vises som UOFFICIEL | Avesmaps. Et identisk navn beviser ikke, at det er den samme indtastning; intet slås nogensinde sammen.",
