    // --- Neuigkeiten (WI-0139) ---
    "news.title": "Nyheder",
    "news.intro":
        "Hvad der er sket på Avesmaps, siden kortet kom online i april 2026 — de større skridt, det med småt lader vi ligge.",
    "news.foot": "Avesmaps er et fanprojekt og bygges løbende videre. Idéer og fejl modtages gerne på vores Discord.",
