    "news.rubrik.ki": "AI",
    "corner.notes": "Oplysninger",
    "notes.title": "Oplysninger",
    "notes.keyboard": "Tastatur",
    "notes.or": "eller",
    "notes.shortcutsOff":
        "Slå tastaturgenveje med enkelte bogstaver, cifre og tegn fra. Piletasterne virker videre. Hjælper, når kortet styres med stemmen.",
    "notes.ringText":
        "Den højre museknap flytter aldrig kortet. På computeren zoomer styreringen øverst til højre (+, −), drejer med pilene til venstre og højre til nærmeste verdenshjørne og retter mod nord i midten; pillen „2D | 3D“ ovenover hælder kortet og gør det fladt igen. På telefonen gør to fingre det; er kortet drejet, står der et kompas, og et tryk på det stiller nord opad. Den runde knap med kortbrikken hælder kortet i 3D og gør det fladt igen.",
    "notes.ringOnTouch": "Vis også styreringen på telefonen. Så kan kortet drejes og zoomes uden to fingre.",
    // „Karten auf Avesmaps“ fasst seit 2026-10-12 zusammen, was vorher „Kartenmaterial“ und „Kartenserien“ getrennt sagten.
    "notes.derivationUndocumented":
        "Hvordan denne udgave er opstået ud fra originalkortet, er udtrykkeligt ikke dokumenteret. Serien bruges lokalt; om en offentlig udlevering besluttes der særskilt.",
    // Der Aufbau nach Legacys #legal-dialog (WI-0045 Stufe B, Betreiber 2026-09-27): Wappenbild, zwei
    // Aktionskacheln, klappbare Abschnitte mit Hinweiszeile. Die Rechtstexte selbst stehen in config/legal.
    "notes.badge": "Ikke-kommercielt fanprojekt",
    "notes.badge.alt": "DSA-fanprojekt-logo",
    "notes.social.lead": "Vær med og følg os",
    "notes.social.body":
        "Spørgsmål, feedback eller bare lyst til at snakke med? Avesmaps-fællesskabet mødes på Discord. På vores kanaler viser vi, hvad der er på vej.",
    "notes.social.action": "Til fællesskabet",
    "notes.kontakt.action": "Skriv en besked",
