    "admin.umgebungen.releaseTest.titel": "Release-test",
    "admin.umgebungen.releaseTest.satz":
        "To knapper. Hurtigtesten kontrollerer den aktuelle stage-version ved release-porten (build, migreringer på rigtige data, kerneforløb i browseren) i en separat klon på denne computer og frigiver den samtidig til produktion: Er den grøn, går præcis denne version selv i produktion. Den fulde test kører først hurtigtesten og derefter alt (alle tests, alle browser-specs); den frigiver intet, og til sidst er der kun rapporten. Rød betyder for begge: Intet går ud, og rapporten nævner alt, der er rødt.",
