    "admin.terrain.test.regler.bereich.form.titel": "Bjergform",
    "admin.terrain.test.regler.bereich.form.satz":
        "Hvordan bjergene af denne type ser ud: højde, bredde, skarphed og ujævnhed. Hver skyder har et lille skema; at trække i den viser straks, hvad værdien gør.",
    "admin.terrain.test.regler.bereich.rinnen.titel": "Render i forhåndsvisningen",
    "admin.terrain.test.regler.bereich.rinnen.satz":
        "Hvad vandet allerede graver i bjergforhåndsvisningen: render på skråningerne og dale langs floder.",
    "admin.terrain.test.regler.bereich.gelaende.titel": "I det færdige terræn",
    "admin.terrain.test.regler.bereich.gelaende.satz":
        "Hvor meget af den tegnede form erosionen af hele terrænet lader stå.",
    "admin.terrain.test.regler.kammhoehe":
        "Hver bjergkæde sætter selv sin kamhøjde (fanen Bjerg); hurtigvalg findes længere nede under højdetrinnene.",
    "admin.terrain.test.regler.alle.titel": "Alle værdier (til finjustering)",
    "admin.terrain.test.regler.alle.kurz": "{n} enkeltværdier",
    "admin.terrain.test.regler.alle.satz":
        "Hver værdi for sig, også dem en skyder ovenfor sætter sammen. Her kan begge halvdele af en fælles skyder sættes forskelligt.",
    "admin.terrain.test.regler.name.massigkeit": "Massivitet",
