    "admin.terrain.test.regler.name.neigung": "Sidetoppenes stejlhed",
    "admin.terrain.test.regler.satz.neigung":
        "Hvor stejlt en sidetop rejser sig: små værdier giver en bred, flad kegle, store en smal spids. Virker kun, når højden er over 0.",
    "admin.terrain.test.regler.wirkt.neigung": "Virker ved tegnede kamme og på bjerge, der kun har sidetoppe.",
    "admin.terrain.test.vorschau.vorher.neigung": "Stiplet: samme top uden hældning, som hidtil.",
