    "admin.karteneinstellungen.panel.sprachen.titel": "Sprog",
    "admin.karteneinstellungen.panel.sprachen.wirkung":
        "Hvilke sprog infoboksene for territorier, derografi og veje nævner.",
    "admin.karteneinstellungen.wert.sprachenMindestanteil.name": "Mindsteandel",
    "admin.karteneinstellungen.wert.sprachenMindestanteil.satz":
        "Fra hvilken andel et sprogområde står i rækken »Sprog« for et territorium, et derografiområde eller en vej: andel af arealet, for en vej af længden. Steder tæller, når deres punkt ligger i sprogområdet. 0 betyder enhver berøring. Standarden er 5 %. Sprogene er stadig under opbygning; indtil da har værdien ingen virkning.",
    "admin.karteneinstellungen.wert.sprachenMindestanteil.einheit": "%",
