    "admin.karteneinstellungen.panel.ozeanShader.titel": "OceanShader til/fra",
    "admin.karteneinstellungen.panel.ozeanShader.wirkung":
        "Om vandet på hav og søer bevæger sig i 3D-visningen, og hvordan det glinser i solen.",
    "admin.karteneinstellungen.wert.ozeanShaderAn.name": "Bevægeligt vand i 3D",
    "admin.karteneinstellungen.wert.ozeanShaderAn.satz":
        "Til: Når kortet er vippet, bevæger vandet sig på hav og søer, på computeren i visningen „Standard“. Fra: Vandet står, som kortet tegner det, og kortet skal ikke hele tiden tegnes igen; det skåner ældre computere. I 2D bevæger vandet sig aldrig.",
    "admin.karteneinstellungen.wert.ozeanGlanzpunkt.name": "Glanspunktets størrelse",
    "admin.karteneinstellungen.wert.ozeanGlanzpunkt.satz":
        "Hvor stor den lyse plet er, hvor solen spejler sig i vandet: større betyder bredere og blødere, mindre betyder skarpere og mere funklende. 1 er standard.",
    "admin.karteneinstellungen.wert.ozeanGlanzpunkt.einheit": "×",
